reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.gallery.admin'),true);
select public.gallery_save_access('{"id":"e9000000-0000-4000-8000-000000000001","slug":"four-character-test","title":"Four","visibility":"private","status":"published","password_required":true}','1234');
do $$begin begin perform public.gallery_save_access('{"slug":"three-character-test","title":"Three","visibility":"private","status":"published","password_required":true}','123');raise exception 'three characters accepted';exception when raise_exception then if sqlerrm='three characters accepted' then raise;end if;end;end;$$;
select public.gallery_save_access('{"id":"e9000000-0000-4000-8000-000000000002","slug":"optional-password-test","title":"Link only","visibility":"private","status":"published","password_required":false}');
reset role;
select set_config('test.gallery.share',(select share_key from dept_gallery_private.access_settings where gallery_id='e9000000-0000-4000-8000-000000000002'),true);
set local role anon;
select pg_temp.gallery_assert(public.gallery_unlock('four-character-test','1234')->>'state'='unlocked','four-character password accepted');
select pg_temp.gallery_assert(public.gallery_resolve('optional-password-test')->>'state'='locked','slug alone does not grant access');
select pg_temp.gallery_assert(public.gallery_unlock_link('optional-password-test',repeat('0',64))->>'state'='invalid','incorrect share key denied');
select set_config('test.gallery.linksession',public.gallery_unlock_link('optional-password-test',current_setting('test.gallery.share'))->>'token',true);
select pg_temp.gallery_assert(public.gallery_resolve('optional-password-test',current_setting('test.gallery.linksession'))->>'state'='authorized','secure link grants scoped session');
select pg_temp.gallery_assert(public.gallery_directory()::text not like '%optional-password-test%','link-only private gallery excluded from directory');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.gallery.admin'),true);
select public.gallery_save_access(jsonb_build_object('id','e9000000-0000-4000-8000-000000000002','slug','optional-password-test','title','Link only','visibility','private','status','published','password_required',true,'revision',(select revision from public.dept_galleries where slug='optional-password-test')),'abcd');
set local role anon;
select pg_temp.gallery_assert(public.gallery_unlock_link('optional-password-test',current_setting('test.gallery.share'))->>'state'='invalid','requiring password revokes old share key');
select pg_temp.gallery_assert(public.gallery_resolve('optional-password-test',current_setting('test.gallery.linksession'))->>'state'='locked','mode change revokes issued sessions');
select pg_temp.gallery_assert(public.gallery_unlock('optional-password-test','abcd')->>'state'='unlocked','re-enabled password works');
reset role;
set local role anon;
select set_config('test.gallery.pin_session',public.gallery_unlock('four-character-test','1234')->>'token',true);
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.gallery.admin'),true);
select public.gallery_save_access(jsonb_build_object('id','e9000000-0000-4000-8000-000000000001','slug','four-character-test','title','Four','visibility','private','status','published','password_required',true,'revision',(select revision from public.dept_galleries where slug='four-character-test')),'5678');
set local role anon;
select pg_temp.gallery_assert(public.gallery_resolve('four-character-test',current_setting('test.gallery.pin_session'))->>'state'='locked','changing PIN revokes prior sessions');
reset role;
